file.content:
[
  {
    "id": "c001",
    "name": "1.1 Employment and application warranty",
    "text": "1.1 Subject to the terms and conditions stated in this Employment Contract (“Contract”), the University hereby employs Michael A. Haywood as Head Football Coach of the University’s varsity intercollegiate football team (“Team”), and Michael A, Haywood hereby accepts said employment. The University and the Employee acknowledge the Employee has completed a University Employment Application form (“Application”). The Employee hereby warrants that he has filled out the Application, which is incorporated herein by reference, ina complete, accurate and truthful manner."
  },
  {
    "id": "c002",
    "name": "2.0 Term",
    "text": "Term The term of this Contract shall be effective on December 16, 2010, and shall expire January 15, 2016, unless otherwise extended or terminated as provided herein (“Term”). A “Contract Year” shall be the annual period of January 16 through the next ensuing January 15, during the Term; except that the first Contract Year shall begin on the effective date of this Contract and shall extend through January 15, 2012."
  },
  {
    "id": "c003",
    "name": "2.0 Extension discussion",
    "text": "Ata mutually convenient time between January 15,2013 and March 31,2013, the Employee and the University’s Director of Athletics shall meet to discuss the Team, this Contract, the Employee’s performance hereunder and the desirability of a possible extension of the Term of this Contract. Atthat time, the University — in its sole discretion — may consider an extension of the Term hereof."
  },
  {
    "id": "c004",
    "name": "3.1 Base salary",
    "text": "The Employee shall receive, as compensation for his services to the University and satisfactory performance of the terms and conditions of this Contract, a base Salary at the per annum rate of One Million Dollars ($1,000,000)."
  },
  {
    "id": "c005",
    "name": "3.1 Salary payment schedule",
    "text": "All such annual base salary shall be paid to the Employee in equal monthly installments, on the last day of each calendar month."
  },
  {
    "id": "c006",
    "name": "3.2 Staff fringe benefits",
    "text": "Except as otherwise specifically and expressly set forth in this Contract, the Employee shall receive the standard staff fringe benefits received by the University's staff, as described in the University of Pittsburgh's Staff Handbook. If any such benefit is based in whole or in part upon salary paid to the Employee, such consideration shall be made without including any income other than the applicable base salary amount as described in provision 3.1 hereof,"
  },
  {
    "id": "c007",
    "name": "3.3 Club membership",
    "text": "The University shall pay initiation fees and monthly membership dues for the Employee at a mutually agreed upon golf or country club, which membership shall be used by the Employee for development and entertainment activities associated with the Employee's official responsibilities."
  },
  {
    "id": "c008",
    "name": "3.4 Automobile",
    "text": "The University shall make available to the Employee, ona loan basis, one (1) dealer-provided automobile from the car dealer program of the University’s Department of Athletics (“Department”), for the Employee’s official and personal use, fully insured by the University; provided that:"
  },
  {
    "id": "c009",
    "name": "3.4(1) Dealer car program condition",
    "text": "(1) The University’s obligation to provide such an automobile shall cease if the dealer car program of the Department is terminated for any reason or if the Employee fails or refuses to comply fully with the University’s requirements for participation in the program."
  },
  {
    "id": "c010",
    "name": "3.4(2) Automobile care condition",
    "text": "(2) The University’s obligation to provide such an automobile shall cease if the Employee fails, at any time, properly to care for said automobile in accordance with the manufacturer’s and the dealer’s specifications and to maintain the said automobile in the same 3.5 3.6 condition existing at the time of receipt by the Employee, reasonable wear and tear excepted."
  },
  {
    "id": "c011",
    "name": "3.4(3) Automobile operating expenses",
    "text": "(3) The Employee shall pay all Operating expenses for the said automobile including without limitation, gasoline and oil."
  },
  {
    "id": "c012",
    "name": "3.4(4) Automobile records",
    "text": "(4) | The Employee shall keep, maintairi and provide to the appropriate University officials any and all written records concerning the use of the automobile as may be required by the University."
  },
  {
    "id": "c013",
    "name": "3.4 Automobile return remedy",
    "text": "If at any time the University reasonably determines the Employee has failed or refused to comply with any of the above-stated requirements, the Employee shall return the automobile to the University, immediately upon the request of the University, and the Employee shall have no right to receive any other automobile from, or through, the University."
  },
  {
    "id": "c014",
    "name": "3.5 Football tickets",
    "text": "During each Contract Year, the University shall provide the Employee, atno cost to him, six (6) season tickets for the Team's home games, and six (6) tickets for any away game in which the Team participates, all of which shall be used for his official responsibilities."
  },
  {
    "id": "c015",
    "name": "3.6 Expense reimbursement",
    "text": "The University shall reimburse the Employee for appropriate travel and outof-pocket expenses reasonably incurred by him for the purpose of and in connection with the performance of his duties under this Contract, including but not limited to NCAA approved expenses incurred while recruiting and scouting. All such reimbursement shall be made in accordance with the standard procedures of the University upon presentation to the University of vouchers or other statements itemizing such expenses in reasonable detail."
  },
  {
    "id": "c016",
    "name": "3.7 Supplemental compensation",
    "text": "While the Employee is serving as the University’s Head Football Coach under this Contract, he shall be entitled to receive supplemental compensation in consideration for his efforts in contributing to the exceptional performance of the Team and for the extra services required of the Employee in preparation for and participation in post-season games of the Team. Specifically, the Employee shall be entitled to the following: A. The greatest of: (1) (2) (3) One Hundred Fifty Thousand ($ 150,000) for a Contract Year in which the Team wins the post-season national championship game, played as a part of the national Bow] Championship Series, or similar successor series; or One Hundred Thousand Dollars ($100,000) for a Contract Year in which the Team participates in, but loses, the post-season national championship game, played as a part of the national Bowl Championship Series, or similar successor series; or One Hundred Thousand Dollars $100,000) for a Contract Year in which the Team participates in one of the post-season bowl games ~ other than the national championship game — generally considered a part of the national Bowl Championship Series, or similar successor series; and seventy Five Thousand Dollars ($75,000) fora Contract Year in which the Team wins the championship football game (if any) or (if there is no such championship game) is generally recognized as the regular season football champion of the Big East Conference (or such other 1 3.8 applicable athletics conference in which the University is then a member, affiliated with and/or competes); and C. Seventy-Five Thousand Dollars ($75,000) for a Contract Year in which the Employee is named national coach of the year by the Associated Press, ESPN, USA Today or other similar nationally-recognized Organization or outlet teasonably acceptable to the University’s Director of Athletics."
  },
  {
    "id": "c017",
    "name": "3.7 Supplemental compensation payment date",
    "text": "All such additional compensation shall be paid on or before the March 15 next following any of the events requiring such payment(s),"
  },
  {
    "id": "c018",
    "name": "3.8 Shoe/Apparel/Equipment Contracts",
    "text": "The parties agree that the University, and not the Employee, shall have the sole and exclusive right and opportunity to enter into a contract, or contracts, with any and all shoe/ apparel /equipment/ supplies /accessories manufacturers and/or distributors for the purpose of committing any or all of the University’s intercollegiate athletics teams, including the Team, to wear or use particular shoes, apparel, equipment, supplies or accessories during practices, games and/or official Team events and activities; and/or for the purpose of committing the Employee (and/or other University employees) to wear, use, promote, endorse Or consult with the manufacturer(s), distributor(s) and/or seller(s) concerning the design or marketing of such shoes, apparel, equipment, supplies or accessories (eacha “Shoe/Apparel/Equipment Contract”). The Employee shall cooperate fully with the University in the University’s efforts to enter into, and to comply with, any and every such Shoe / Apparel/Equipment Contract, including but not limited to participating in such promotional activities as are required in any and every such Shoe/ Apparel / Equipment Contract."
  },
  {
    "id": "c019",
    "name": "3.9 Shoe/Apparel/Equipment revenue and compensation",
    "text": "Any and all revenue resulting from any Shoe/Apparel/ Equipment Contract shall be the sole and exclusive property of the University. Nonetheless, for services rendered by the Employee in connection with any such contracts, while the Employee is representing the University as Head Football Coach the Employee shall be paid by the University, the sum of One Hundred Fifty Thousand Dollars ($150,000) per year, during each Contract Year. The applicable amounts shall be payable to the Employee, in each Contract Year, in two (2) equal installments to be paid on or before the first day of September and the first day of January (by January 1, 2012 for the first Contract Year)."
  },
  {
    "id": "c020",
    "name": "3.9 Publicity rights",
    "text": "In relation to the subject of, and the matters described in, this provision 3.8, and for the purpose of promoting the Team and the University’s intercollegiate athletics program generally, the Employee hereby consents to, acknowledges and agrees that the University shall have the right (and shall be permitted to assign such right to others) to use the Employee’s name, nickname, likeness (actual, simulated, caricature or otherwise), ima Ze, voice, personality, signature and/or other publicity right."
  },
  {
    "id": "c021",
    "name": "3.10 Private stadium box",
    "text": "Subject to the facility owner’s standard conditions, the Employee shall, in addition to the tickets described in provision 3.5, be provided the complimentary use of a private stadium box, as assigned or re-assigned by the University, for and during each of the University’s home football games at Heinz Field, Pittsburgh, Pennsylvania."
  },
  {
    "id": "c022",
    "name": "4.1 Full time and attention",
    "text": "While employed as the University’s Head Football Coach, the Employee shall devote his full time, attention and energies to his duties as Head Footbal] Coach, including such related duties in the intercollegiate athletics program of the University as may be assigned to him by the University’s Director of Athletics, subject to any exceptions hereinafter expressly described. He shall also select such assistants and applicable staff, as authorized by the University, who shall be committed, likewise, to devoting their full time, attention and energies to the furtherance of the athletics program of the University. The Employee shall comply fully with the legislation, rules, regulations and policies of the National Collegiate Athletic Association (“NCAA”), of the Big East Conference (or such other applicable athletics conference in which the University is then a member, affiliated with and/or competes) of the University and of the Department (including without limitation the mission statements of the University and of the Department and the principles of “The Pitt Promise”), and he shall take every precaution to ensure that all members of his staff comply fully with such legislation, rules, regulations and policies."
  },
  {
    "id": "c023",
    "name": "5.1 Direction of Director of Athletics",
    "text": "The Employee's immediate supervisor, for purposes of implementing this Contract, shall be the Director of Athletics of the University, and all matters pertaining to the operation of the University’s athletics program including, but not limited to, those set forth in provisions 5.2 and 5.3 below, shall be subject to the direction and control of the said Director of Athletics."
  },
  {
    "id": "c024",
    "name": "5.2 Performance evaluations",
    "text": "The Employee shall cooperate with performance evaluation(s) of his performance to be conducted in the same manner and on the same basis as performance evaluations are conducted for other University staff, taking into account this Contract, prior performance evaluations of the Employee and the expectations and goals previously agreed upon by the Employee and the University’s Director of Athletics."
  },
  {
    "id": "c025",
    "name": "5.3 Employee duties",
    "text": "In addition to other duties as described in this Contract, the Employee shall give proper time and attention to, and shall perform in good faith and to the best of his ability, the following duties: (1) promoting the athletic, academic and social welfare of the student-athletes in his charge; (2) recruiting, teaching, supervising and evaluating student-athletes in his charge; (3) recruiting, teaching, supervising and evaluating the performance of assistant coaches and other football staff members; (4) managing the Team budget; (5) complying with NCAA legislation, rules, regulations and policies (“NCAA Rules”); (6) avoiding the imposition of any academic disincentive penalty on the Team, as described in NCAA Rules (by way of example only, pursuant to an NCAA academic performance program); (7) maintaining a good working relationship.with the University community; (8) conducting public relations related to the University’s football program, including relations with media, alumni, boosters and the general public which reflect positively on the University; and (9) such other duties as assigned from time to time by the University’s Director of Athletics."
  },
  {
    "id": "c026",
    "name": "5.4 NCAA discipline",
    "text": "Without limiting any other provision of this Contract, if the Employee is found to be in, or to have been in, violation of NCAA Rules, either while employed by the University (in any capacity, pursuant to this Contract or otherwise) or during prior employment at another NCAA member 6.0 7.0 institution, the Employee shall be subject to disciplinary or corrective action as set forth in the provisions of the NCAA enforcement procedures, including suspension without pay or termination of employment for significant or repetitive violations."
  },
  {
    "id": "c027",
    "name": "6.1 Academic policy",
    "text": "The Employee shall recognize that the primary mission of the University is education, and the Employee shall perform his duties as described herein and administer the University’s football program with proper regard for the academic welfare of the student-athletes in the University’s football program and fully consistent with the academic standards and policies of the University. The Employee shall perform his duties as described herein and administer the University’s football program in accordance with academic policies established by the University’s Chancellor and the University’s Board of Trustees,"
  },
  {
    "id": "c028",
    "name": "6.2 Athletics policy",
    "text": "Overall athletics policy shall remain the exclusive prerogative of the University. The Employee shall perform under this Contract and administer the University’s football program in accordance with athletics policies established by the University’s Chancellor and the University’s Board of Trustees."
  },
  {
    "id": "c029",
    "name": "7.1 Decisions affecting football program",
    "text": "7.1 The University, through its Director of Athletics, shall permit the Employee to offer input on decisions relating to choice and scheduling of the Team’s opponents, means of travel to be employed by the Team, hotel and food accommodations applicable to the Team, size and content of the Team’s traveling squad, and other matters pertaining to the operation of the Team, but final decisions in all such matters shall rest with the University’s Director of Athletics."
  },
  {
    "id": "c030",
    "name": "8.1 Marketing, appearances and fundraising",
    "text": "8.1 The Employee shall make himself available for, participate in and cooperate fully with the University’s marketing and promotion of the Team and the University’s intercollegiate athletics program, and with media and other public and private appearances, at such times and places as the University may reasonably require. Further, the Employee shall make himself available for, participate in and cooperate fully with public and private fund raising and development activities at such times and places as the University may reasonably require — which activities may include, but shall not be limited to , cultivation of donors and potential donors to the University and events organized by sponsors of the University."
  },
  {
    "id": "c031",
    "name": "8.2 Programs participation",
    "text": "8.2 The Employee shall make himself available for, participate in and cooperate fully with the production and marketing of any and all shows and programs (including but not limited to call-in shows and specials relating to playoff or bowl games) distributed via terrestrial radio, satellite radio, television, internet, computer, mobile device, wireless device and/or any other media in which the subject is, in whole or in part, the Team and/or University 11 8.3 8.4 intercollegiate athletics (the “Programs”), as arranged by the University or the University’s designee (including but not limited to ISP Sports, LLC)."
  },
  {
    "id": "c032",
    "name": "8.3 Program services and intellectual property",
    "text": "The Employee shall perform such reasonable services as may be requested by the University, or the University’s designee, and/or as may be specified in the University’s or the University’s designee’s contract(s) with the producers and distributors of Programs. The Employee shall not appear on or in any competing shows or programs without the prior written consent of the University’s Director of Athletics. As between the University and the Employee, the University shall own any and all intellectual property and other rights in and to such Programs."
  },
  {
    "id": "c033",
    "name": "8.4 Program revenue and compensation",
    "text": "Any and all revenue resulting from the Programs, and other matters described in provisions 8.1, 8.2 and 8.3, shall be the sole and exclusive property of the University. Nonetheless, for services rendered by the Employee in connection therewith, while the Employee is representing the University as Head Football Coach the Employee shall be paid by the University, the sum of Three Hundred Fifty Thousand Dollars ($350,000) per year, during each Contract Year."
  },
  {
    "id": "c034",
    "name": "8.4 Compensation payment schedule",
    "text": "The applicable amounts shall be paid to the Employee, in each Contract Year, in two (2) equal installments to be paid on or before the first day of September and the first day of January (by January 1, 2012 for the first Contract Year)."
  },
  {
    "id": "c035",
    "name": "8.4 Program publicity rights",
    "text": "In relation to the Programs, the other matters described in provisions 8.1 and 8.2, above, and for the purpose of promoting the Team and the University’s intercollegiate athletics program generally, the Employee hereby consents to, acknowledges and agrees that the University shall have the right (and shall"
  },
  {
    "id": "c036",
    "name": "9.1 Football camp conditions",
    "text": "form acceptable to the University; naming the University as an additional insured; providing the University with a copy of each certificate of insurance for such insurance; and, at the University’s discretion, entering into a written contract upon standard University terms for similar third-party uses of University facilities, including the obligation to indemnify, defend and hold harmless the University from any loss."
  },
  {
    "id": "c037",
    "name": "9.2 Camp facility arrangements",
    "text": "The Employee shall consult with the University’s Director of Athletics no Jater than ten (10) months in advance of any planned football camp(s) regarding the availability of the athletics facilities the Employee desires to use. Once the University has agreed to make specific facilities available for any particular football camp(s), it shall not change the applicable facilities arrangement for the particular camp(s) unless it gives the Employee at least ninety (90) days’ notice (in which case it will incur no liability for the change) or the Employee consents to the change. The Employee shall not unreasonably withhold consent when reasonable alternative facilities are offered by the University."
  },
  {
    "id": "c038",
    "name": "9.3 NCAA camp terms",
    "text": "The University shall deal with the Employee on matters concerning the football camp(s) under terms and conditions consistent with those then established by the NCAA for the operation of college football camps."
  },
  {
    "id": "c039",
    "name": "9.4 Camp records",
    "text": "The Employee shall maintain, keep and retain such accurate and complete financial, and other, records concerning such camps as the University may, from time to time, request. Upon receipt of a request by the University, the Employee shall provide access to such records, and to all other camp records, within ten (10) days."
  },
  {
    "id": "c040",
    "name": "9.5 Camps after termination or expiration",
    "text": "In the event of termination of this Contract by either party, or expiration hereof, the University shall be under no obligation to permit any football camp to be held by the Employee, after the effective date of such termination or expiration (whether or not one has been planned), and the University shall be released from all obligations relating thereto immediately upon such termination or expiration."
  },
  {
    "id": "c041",
    "name": "10.1 Outside business activities",
    "text": "While serving as the University’s Head Football Coach, the Employee shall be prohibited from publicly using, and shall be prohibited from permitting or licensing any other person or entity publicly to use, the Employee’s name, nickname, likeness (actual, simulated, caricature or otherwise), image, voice, personality, signature and/or other publicity right to market, promote, advertise, sponsor, sell or endorse any product, good, service, cause or position without the prior written approval of the University’s Director of Athletics and the University’s Chancellor. Without limiting the foregoing, the Employee shall be permitted to contract independently with outside sources for separate and additional compensation which shall inure to his benefit, subject to the prior written approval of the University’s Director of Athletics and the University’s Chancellor. The Employee shall not permit the use of any of the University’s names, logos, symbols, designs, colors, team names, nicknames, mascots, slogans, abbreviations, trademarks or service marks in any such activities without the prior written approval of the University’s Director of Athletics and the University’s Chancellor."
  },
  {
    "id": "c042",
    "name": "10.1 Use of University property",
    "text": "To the extent the University’s facilities or other property may be desired by the Employee for use in such activities (which shall require the prior approval of the University’s Director of Athletics), the Employee shall first 15 enter into a separate written contract for the same on terms and conditions acceptable to the University."
  },
  {
    "id": "c043",
    "name": "10.1A University Obligations Are Primary",
    "text": "University Obligations Are Primary. Such outside activities shall not interfere with the full and complete performance by the Employee of his duties and obligations as a University employee, recognizing always that the Employee's primary obligations are to the University."
  },
  {
    "id": "c044",
    "name": "10.1B NCAA, Conference and University Rules Control",
    "text": "NCAA, Conference and University Rules Control. Inno event shall the Employee accept or receive directly or indirectly any monies, benefits or any other gratuity whatsoever from any person, corporation, University booster club or alumni association or other benefactor if such action would violate NCAA Rules or the Big East Conference's (or such other applicable athletics conference in which the University is then a member, affiliated with and/or competes) or the University’s constitution, mission, legislation, bylaws, rules, policies or regulations. Changes in such NCAA Rules or the applicable conference’s or the University’s constitution, mission, legislation, bylaws, rules, policies or regulations or interpretations thereof shall automatically apply to this Contract without the necessity of a written modification."
  },
  {
    "id": "c045",
    "name": "10.1C University Is Not Liable",
    "text": "University Is Not Liable. Such activities are independent of the Employee's University employment, and the University shall haveno responsibility or liability for any claims arising therefrom. The Employee further agrees to indemnify, defend and hold harmless the University and its trustees, employees, agents, officers and assigns from and against any and all suits, judgments, actions, causes of 16 action, claims, demands, liabilities, injuries, losses, damages, expenses and costs (including but not limited to attorney's fees) which arise from, are caused by or are associated with the Employee's, his employees’, contractors’, assigns’ or agents’, performance of any such outside activities or contracts."
  },
  {
    "id": "c046",
    "name": "10.1D Employee Retains all Revenues",
    "text": "D. Employee Retains all Revenues. Except for the limitations on such outside compensation as established by or set forth in this Contract or in the constitution, mission, le gislation, bylaws, rules, policies and/or regulations and interpretations thereof of the University, or the Big East Conference (or such other applicable athletics conference in which the University is then a member, affiliated with and/or competes) or the NCAA, the Employee shall be entitled to retain all revenue generated by such outside activities, The Employee, in accordance with NCAA Rules, shall provide a detailed written report (at least annually and no later than the date(s) the University’s Director of Athletics shall designate) of all athletically related income and benefits from sources outside the University (including, but not limited to, income from annuities, sports camps, housing benefits, country club memberships, complimentary ticket sales, television and radio programs and endorsement or consultation contracts with athletic shoe, apparel or equipment manufa cturers) to the University’s Director of Athletics and the University’s Chancellor."
  },
  {
    "id": "c047",
    "name": "10.1E University Opportunities",
    "text": "E. University Opportunities. In no event shall the Employee be permitted to usurp any corporate opportunities of the University or engage in any activity causing a conflict of interest with his University employment."
  },
  {
    "id": "c048",
    "name": "10.1F University Policy",
    "text": "F, University Policy. Further, the approval of all athletically related income and benefits shall be consistent with the University’s polices 17 then in effect related to outside income and benefits applicable to other University full-time or part-time staff."
  },
  {
    "id": "c049",
    "name": "11.1 Vacation entitlement",
    "text": "Ineach Contract Year, the Employee shall be entitled to twenty (20) days of vacation (equivalent of four (4) working weeks), with compensation, so long as the timing of use of any such vacation is approved, in advance, by the University’s Director of Athletics."
  },
  {
    "id": "c050",
    "name": "11.1 Unused vacation",
    "text": "All such vacation time must be used by the Employee prior to the termination or expiration of this Contract. The Employee shall not be permitted to retain any such unused vacation time after the expiration or termination date of this Contract (for example during a renewal term of this Contract, if any) and shall be entitled to no compensation for any unused vacation time."
  },
  {
    "id": "c051",
    "name": "11.1 Exclusive vacation terms",
    "text": "The foregoing paragraphs of this provision 11.1 shall exclusively govern matiers pertaining to the Employee’s vacation time, notwithstanding anything contained herein or in University rules, regulations or policies to the contrary."
  },
  {
    "id": "c052",
    "name": "12.1 Assistant coaches and football staff",
    "text": "While employed in the capacity of Head Football Coach, the Employee shall have authority to select, hire, establish the salaries of, and dismiss assistant football coaches, a Director of High School Relations and a Director of Football Operations, all subject to the prior approval of the University’s Director of Athletics, in accordance with University policy, and to direct the scope of their duties. The said Director of Football Operations shall have a 18 dual reporting relationship to the Head Football Coach and to the University’s Director of Athletics. The parties hereby agree that the University’s allotted budget for the costs of employment of all such individuals shall not be less than One Million Nine Hundred Thousand Dollars ($1,900,000) per Contract Year, and the Employee shall ensure the costs of employment of all such individuals shall remain within the University's allotted budget for said purposes."
  },
  {
    "id": "c053",
    "name": "13.1 Additional services compensation",
    "text": "Upon the recommendation of the Employee, but subject to the prior approval of the University’s Director of Athletics, each University assistant football coach designated by the Employee may be paid an additional one (1) month’s salary, at the rate then in effect for each such assistant to compensate the assistant for additional services rendered with re gard to any post-season bowl game, during the Term, to which the Team is invited and participates. Such recommendations shall be made to the Director of Athletics no later than the January 15 immediately following the conclusion of each such postseason bowl game. All such properly approved compensation shall be paid on or before the March 31 next following each such post-season bow] game."
  },
  {
    "id": "c054",
    "name": "14.1 Termination for just cause",
    "text": "Notwithstanding any other provisions hereof, the University may at any time, with just cause, terminate this Contract or suspend the Employee with or without pay. In the event of such termination, the University shall be relieved of all further obligations (financial and otherwise) to Employee. Termination of this Contract for just cause shall not prohibit the University from pursuing any and all other legal rights or remedies available to it."
  },
  {
    "id": "c055",
    "name": "14.1 Definition of just cause",
    "text": "For the purposes of this Contract, “just cause” shall mean, in addition to its normally understood meaning in employment contracts, any one or more of the following: A, any conduct by Employee resulting in his conviction of a violation of a criminal statute: or any violation of NCAA Rules by Employee, while employed by the University (in any capacity, pursuant to this Contract or otherwise) or while he was previously employed at another NCAA member institution; or any violation of NCAA Rules by any coach; employee; staff member; student-athlete; or representative of his institution’s athletics interests, with Employee’s prior knowledge and consent, or of which Employee reasonably should have known and prevented, or of which Employee learned at any time but failed to report to his institution, while Employee is employed by the University (in any capacity, pursuant to this Contract or otherwise) or while he was previously employed at another NCAA member institution; or misappropriation or misuse of University funds by Employee; or any breach of Employee’s warranties, duties or obligations described in this Contract; or as determined by the University, any conduct of Employee that is seriously prejudicial to the best interests of the University or its intercollegiate athletics program; that violates the University’s or the 20 Department’s then-current mission; that brings the University into disrepute; or that reflects dishonesty, disloyalty, willful misconduct, gross negligence, moral turpitude or refusal or unwillingness to perform his duties; or G. any conduct by Employee that violates or breaches the published mission, rules, regulations or policies of the University or the Department."
  },
  {
    "id": "c056",
    "name": "14.2 Termination without just cause",
    "text": "14.2 In addition to its rights as described in provision 14.1, the University shall 14.3 have the right to unilateral termination of this Contract without Just cause, Such unilateral termination by the University without just cause shall be effectuated by delivering to Employee written notice of the University's intent so to terminate this Contract. If, but only if, the University exercises its right to unilateral termination under this provision 14.2, Employee shall be entitled to liquidated damages in, and only in, the amount of Seven Hundred Fifty Thousand Dollars ($750,000) per Contract Year, pro rated, for the thenunexpired Term of this Contract, and such payment obligation shall survive the said termination of this Contract."
  },
  {
    "id": "c057",
    "name": "14.2 Liquidated damages payments",
    "text": "All such liquidated damages shall be paid as if salary, in equal monthly installments in the manner described in provision 3.1. The unilateral termination of this Contract by the University shall be deemed a “separation from service” under Internal Revenue Code section 409A, such that the University has determined that the Employee will provide no further services to the University."
  },
  {
    "id": "c058",
    "name": "14.3 Mitigation",
    "text": "Notwithstanding the requirements of provision 14.2, the Employee shall attempt to mitigate the University’s obligations to pay liquidated damages 21 14.4 under provision 14.2 by making reasonable and diligent efforts to obtain other employment, as soon as reasonably possible after termination of this Contract by the University without just cause. As of the date the Employee begins any other employment, the University's financial obligations under this Contract, including provision 14.2, shall cease; except that, if the Employee's compensation, from any source (exclusive of the value of standard fringe benefits available to all employees of such employer), in such other employment is less than the amount the University would be required to pay Employee under provision 14.2, the University shall pay him the difference between the two in the same method as described in provision 14.2 hereof."
  },
  {
    "id": "c059",
    "name": "14.3 Survival",
    "text": "It is hereby agreed that this provision 14.3 shall survive the expiration or earlier termination of this Contract."
  },
  {
    "id": "c060",
    "name": "14.4 Post-termination NCAA violation",
    "text": "Notwithstanding the requirements of provision 14.2, in the event the NCAA, after the Employee's termination, finds that there was a violation of NCAA Rules committed by the Employee (or by a coach; employee; staff member; student-athlete; or representative of the University’s athletics interests with Employee’s prior knowledge and consent, or of which Employee reasonably should have known and prevented, or of which Employee learned at any time but failed to report to the University), the University shall have the right immediately to terminate all future payments due hereunder, to recover past payments made under provision 14.2, and to pursue any and all other legal remedies available to it."
  },
  {
    "id": "c061",
    "name": "14.4 Survival",
    "text": "It is hereby agreed that this provision 14.4 shall survive the expiration or earlier termination of this Contract."
  },
  {
    "id": "c062",
    "name": "14.5 Employee resignation and liquidated damages",
    "text": "14.5 The Employee acknowledges and agrees that his promise to serve the University as Head Football Coach for the entire Term is of the essence of this Contract, and that the University is making a substantial investment in the Employee’s continued employment by entering into this Contract, which investment would be lost if the Employee were to resign prior to the expiration of the Term. Therefore, should Employee unilaterally resign or otherwise terminate his employment with the University before the expiration of this Contract (for which he shall deliver written notice thereof to the University no later than thirty (30) days prior to the effective date of resignation or termination), such shall constitute a material breach of this Contract and the University shall be entitled to, and the Employee shall pay the University, liquidated damages in one lump sum, payable within sixty (60) days from the effective date of such resignation or termination, in an amount calculated as follows: A. If notice of such resignation or termination is given, or if such resignation or termination is effective, at any time during the first four Contract Years (i.e. December 16, 2010—January 15, 2015), the amount payable shall be Three Million Dollars ($3,000,000); and B. If notice of such resignation or termination is given, or if such resignation or termination is effective, at any time during the fifth Contract Year (i.e. January 16, 2015 - January 15, 2016), the amount payable shall be One Million Five Hundred Thousand Dollars ($1,500,000); and such payment obligation shall survive the said resignation and/or termination of this Contract. 23 14.6 14.7 The referenced amount shall serve as liquidated damages to compensate the University for the actual damages that are likely to be suffered by the University due to the Employee’s premature departure. Those reasonably anticipated damages would include costs associated with recruiting a new head football coach, loss of continuity in the football program, reduced ticket sales and lost contributions to the University. Because the actual damages that the University would sustain, if the Employee were to unilaterally resign or terminate his employment with the University under this provision 14.5, are uncertain and would be impossible or very difficult to ascertain fully and accurately, the parties agree in good faith that the above-described payment would be reasonable and just compensation for the harm caused by such breach."
  },
  {
    "id": "c063",
    "name": "14.6 Prospective employment discussions",
    "text": "Unless the University has then already given the Employee written notice of termination under provision 14.1 or provision 14.2 of this Contract, or unless the Employee has then already resigned or terminated his employment with the University in accordance with provision 14.5 of this Contract, the Employee shall not seek, apply for, discuss or negotiate, either directly or indirectly, his prospective employment with any other institution of postsecondary education or any professional athletic team or organization without first.informing, and obtaining the consent of, the University’s Director of Athletics."
  },
  {
    "id": "c064",
    "name": "14.7 Death",
    "text": "In the event of the Employee's death before this Contract has otherwise terminated or expired, the Contract and the University’s obligations, financial and otherwise, shall be deemed to terminate immediately, but the Employee's estate shall receive his full salary and fringe benefits through the date on which his death occurred."
  },
  {
    "id": "c065",
    "name": "14.8 Disability",
    "text": "In the event of Employee’s disability, such that A. he is unable substantially to perform his obligations under this Contract by reason of any medically determinable physical or mental impairment that can be expected to result in death or that can be expected to last for a continuous period of not less than twelve (12) months; or B. by reason of any such impairment he is receiving income replacement benefits for a period of not less than three (3) months under the University’s long-term disability benefits program for staff; then this Contract and the University’s obligations, financial and otherwise, as well as Employee’s requirement to provide additional services, shall terminate immediately."
  },
  {
    "id": "c066",
    "name": "14.9 Return of University property",
    "text": "Upon termination, for any reason, or other expiration of this Contract, the Employee shall, no later than five (5) days after such termination or expiration, return to the University all equipment, keys, documents, employee identification cards, automobiles and other property of any kind belonging to, or provided by or through, the University in his Possession, custody or control."
  },
  {
    "id": "c067",
    "name": "14.9 Survival",
    "text": "It is hereby agreed that this provision 14.9 shall survive the expiration or earlier termination of this Contract."
  },
  {
    "id": "c068",
    "name": "14.10 Cessation of University obligations",
    "text": "Immediately upon expiration or any other termination of this Contract, as described herein, all obligations of the University to make payments to the Employee or to provide consideration hereunder, except as and to the extent 25 14.11 expressly described in provisions 14.2, 14.3, 14.4, 14.7, and 14.8, as and if applicable, shall cease as of the date of such expiration or termination. Inno case shall the University be liable to the Employee for the loss of any collateral business opportunities or any other benefits, perquisites or income."
  },
  {
    "id": "c069",
    "name": "14.11 Noncompetition covenant",
    "text": "Notwithstanding any other provision in this Contract to the contrary, if the Employee should unilaterally resign or otherwise terrninate his employment with the University before the expiration of this Contract, as described in provision 14.5 above or otherwise, the Employee hereby agrees not to obtain or accept employment relating to the sport of football within the Commonwealth of Pennsylvania and/or at any other Big East Conference (or such other applicable athletics conference in which the University is a member, affiliated with and/or competes at the time of such resignation or termination) member-institution for a period commencing on the date the Employee properly delivers notice of such resignation or termination to the University, and ending one (1) year after the date of such delivery."
  },
  {
    "id": "c070",
    "name": "14.11 Survival and equitable relief",
    "text": "It is hereby agreed that this provision 14.11 shall survive the expiration or earlier termination of this Contract and that money damages alone would be inadequate to remedy a breach of the covenant described in this provision 14.11, and that the University shall have the right to obtain such equitable, injunctive or other relief as it may deem appropriate, including but not limited to a decree enjoining the Employee from violating this provision. The Employee hereby agrees this covenant is reasonably limited in duration and geographic scope, and is necessary to protect the legitimate interests of the University."
  },
  {
    "id": "c071",
    "name": "15.1 Equal opportunity",
    "text": "This Contract shall be governed by, and the parties hereto shal] adhere to, those principles and precepts and regulations that relate to equal Opportunity employment and to forbearance from discrimination based upon race, color, sex, age, religion, national origin, marital status, ancestry, familial status, sexual orientation, gender identity and expression, genetic | information, disability or veteran status."
  },
  {
    "id": "c072",
    "name": "16.1 Non-discrimination and other policies",
    "text": "The Employee shall familiarize himself with the non-cliscrimination and other policies of the University and shall abide by their provisions in all dealings with University employees, students, Prospective students and others."
  },
  {
    "id": "c073",
    "name": "17.1 Contract confidentiality",
    "text": "The Employee and the University (and the advisors, tepresentatives, officers, directors, trustees, employees and agents, if any, of the parties) shall keep this Contract confidential, and shall not use any information contained herein for any purpose other than the purposes contemplated under this Contract. Each party acknowledges the importance of maintaining the security and confidentiality of this Contract and agrees to take whatever measures are necessary to prevent the unauthorized or ina dvertent transfer, disclosure, access or use of the information contained herein to or by any third party. Each party hereto agrees to ensure that the terms and conditions of this Contract are adhered to by all persons who have access to the information contained herein through such party, including employees, 2/ 17.2 advisors, representatives, and agents, and shall be responsible for breaches of confidentiality by its/his own employees, advisors, representatives, agents and other persons who gain access to any such information through such recipient party. The information contained herein shall be disclosed only to those persons who are actively and directly participating in the performance of this Contract and who need to know’such information, and each party shall use best efforts to inform the receiving party of the sensitive nature of such information and shall direct the receiving party to keep such information confidential."
  },
  {
    "id": "c074",
    "name": "17.1 Survival and equitable relief",
    "text": "It is hereby agreed that this provision 17.1 shall survive the expiration or earlier termination of this Contract, and that money damages alone would be inadequate to remedy a breach of this provision 17.1, and that the nonbreaching party shall have the right to seek such equitable, injunctive or other relief as it may deem appropriate, including but not limited to a decree enjoining the breaching party from violating this provision."
  },
  {
    "id": "c075",
    "name": "17.2 Private information definition",
    "text": "The Employee acknowledges and agrees that during the course of his employment with the University he has and/or will become knowledgeable about the affairs of the University, including private information. For purposes of this provision 17.2, “private information” shall be defined as information disclosed to Employee or known by Employee asa consequence of his employment, and not generally known outside the University."
  },
  {
    "id": "c076",
    "name": "17.2 Protection of private information",
    "text": "During the Employee’s employment and after the expiration or termination of his employment with the University, the Employee will hold the private information of the University in trust and confidence, and will not use or disclose it or any embodiment thereof, clirectly or indirectly, except as may be absolutely necessary in the performance of his duties for the University."
  },
  {
    "id": "c077",
    "name": "17.2 Harm from disclosure",
    "text": "The Employee acknowledges that any such disclosure could be highly damaging to the University and its employees, students, alumni, donors or others."
  },
  {
    "id": "c078",
    "name": "17.2 Private information materials",
    "text": "The Employee shall not remove materials containing private information from the offices of the Department of Athletics, unless authorized to do so by the University’s Director of Athletics. Any and all such materials are the property of the University and, upon expiration of this Contract or other termination of Employee’s employment with the University (as described in provision 14.9), or upon termination of any assignment for which such materials are necessary or as requested by the University’s Director of Athletics, Employee will return all such materials and copies thereof to the University’s Department of Athletics."
  },
  {
    "id": "c079",
    "name": "17.2 Survival and equitable relief",
    "text": "It is hereby agreed that this provision 17.2 shall survive the expiration or earlier termination of this Contract, and that money damages alone would be inadequate to remedy a breach of this provision 17.2, and that the University shall have the right to obtain such equitable, injunctive or other relief as it may deem appropriate, including but not limited to a decree enjoining the Employee from violating this provision."
  },
  {
    "id": "c080",
    "name": "17.3 Required disclosure exception",
    "text": "Notwithstanding anything contained in provision 17.1 to the contrary, neither party shall be prohibited from disclosing confidential information to the extent required of them by law or by NCAA Rules or by applicable athletics conference rules."
  },
  {
    "id": "c081",
    "name": "18.1 Notices",
    "text": "18.1 All notices contemplated by this Contract shall be properly and effectively given if delivered personally or by overnight courier or mailed, by US. certified mail, return receipt requested, to the address of the other party as follows: University: To the Director of Athletics at his/her University address. Employee: To his University address or to his home address last communicated in writing to the University’s Director of Athletics"
  },
  {
    "id": "c082",
    "name": "19.1 Binding effect",
    "text": "19.1 This Contract shall be binding upon and shall inure to the benefit of the parties."
  },
  {
    "id": "c083",
    "name": "20.1 Internal grievance procedure",
    "text": "20.1 In the event the Employee has a grievance concerning the terms and ~ conditions of his employment, he will first discuss the matter with the University’s Director of Athletics in an effort to resolve the matter. If the matter remains unresolved after the Employee has discussed it with the University’s Director of Athletics, or ifthe Employee is not reasonably able to _ discuss the particular matter with the University’s Director of Athletics, the Employee may discuss the matter with the University’s Executive Vice Chancellor. The decision of the Executive Vice Chancellor shall be final within the University. This shall be the exclusive internal dispute resolution mechanism by which the Employee may address any grievance internally. 30 Neither the “Employee Inquiry And Complaint Procedures” of the University’s Staff Handbook, nor any other internal dispute resolution mechanism, shall be applicable."
  },
  {
    "id": "c084",
    "name": "20.1 Court jurisdiction and venue",
    "text": "Notwithstanding the foregoing, nothing herein shall prevent either party from submitting disputes and/or grievances pertaining to this Contract to the proper federal or state court within Allegheny County, Pennsylvania, and each party agrees and consents that jurisdiction and venue for any such action shall be in a court of appropriate jurisdiction in Allegheny County, Pennsylvania."
  },
  {
    "id": "c085",
    "name": "20.1 Confidential treatment",
    "text": "All disputes and grievances shall be treated confidentially by both parties, at all times."
  },
  {
    "id": "c086",
    "name": "21.1 Captions",
    "text": "21.1 The captions of the paragraphs and sections of this Contract are used solely for convenience of reference and shal] not control or affect the meaning or interpretation of any of the provisions of this Contract."
  },
  {
    "id": "c087",
    "name": "22.1 Governing law",
    "text": "22.1 This Contract shall be governed by and construed under the laws of the Commonwealth of Pennsylvania, without regard to conflicts of laws principals."
  },
  {
    "id": "c088",
    "name": "23.1 Severability",
    "text": "If any provision of this Contract shall be determined to be void, invalid, unenforceable or illegal for any reason, the Contract shall be ineffective only to the extent of such prohibition and the validity and enforceability of all the remaining provisions shall not be affected thereby,"
  },
  {
    "id": "c089",
    "name": "24.1 Entire agreement, amendment and assignment",
    "text": "This Contract constitutes the entire agreement between the parties with respect to the subject matter hereof, and supersedes all previous and contemporaneous negotiations, commitments and understandings, whether verbal or written. This Contract shall not be released , discharged, amended or modified ; many manner, except by an instrument in writing signed by both of the parties. This Contract is personal to the parties and shall not be subject to assignment by either of them, except as and to the extent expressly provided or contemplated herein."
  },
  {
    "id": "c090",
    "name": "24.2 Taxes and benefit modifications",
    "text": "Any payment of taxes owed on compensation, payments and / or benefits provided by the University to or on behalf of the Employee, which are not expressly an obligation of the University hereunder, shall be the responsibility of the Employee. With respect to the compensation, payments and benefits set forth in this Contract: (a) the Employee shall be responsible for any taxes or other government impositions for which employees are normally responsible; (b) the University shall have the ri ght to comply with any applicable withholding or reporting requirements relatin g to those taxes and impositions; (c) the University shall not be required to do anything that is prohibited (or would prejudice the University's compensation or benefit programs generally) under tax or other laws, regulations and ordinances; 32 24.3 24.4 24.5 and (d) the University reserves the right to modify benefits hereunder if, and to the extent that, they are part of a larger program that is modified for all other employees in the program. The University shall not be required to replace or compensate the Employee for any changes in compensation or benefits pursuant to this paragraph."
  },
  {
    "id": "c091",
    "name": "24.2 Survival",
    "text": "It is hereby agreed that this provision 24.2 shall survive the expiration or earlier termination of this Contract."
  },
  {
    "id": "c092",
    "name": "24.3 Compliance with law",
    "text": "Each party agrees to, and shall, perform its/his obligations under this Contract in accordance with all applicable laws, rules and regulations now or hereafter in effect."
  },
  {
    "id": "c093",
    "name": "24.4 Waiver",
    "text": "No waiver of any provision of this Contract shall be deemed or shall constitute a waiver of any other provision hereof (whether or not similar), nor shall such waiver constitute a continuing waiver unless otherwise expressly provided."
  },
  {
    "id": "c094",
    "name": "24.5 Force majeure",
    "text": "If either party is unable to perform any of its obligations under this Contract due to events beyond its reasonable control, such shall not be considered a breach of this Contract. In such case, to the extent delayed performance is feasible and desired by the other party the time provided for performing such obligations shall be extended by a period of time equal to the duration of such events. Events beyond a party’s reasonable control may include, but shall not be limited to, acts of God, war, civil commotion, fire, flood or other casualty and government regulation or restriction, provided the same renders a party’s performance impossible or unreasonably difficult."
  },
  {
    "id": "c095",
    "name": "24.6 Cumulative remedies",
    "text": "Pursuit by a party of any of the remedies described herein, or otherwise available at law or in equity, shall not preclude pursuit by that party of any other remedy or remedies provided herein or otherwise available at law or in equity. All remedies, rights, undertakings, obligations and agreements shall be cumulative and none of them shall be in limitation of any other remedy, right, undertaking, obligation or agreement of either party."
  },
  {
    "id": "c096",
    "name": "24.7 NCAA indemnification",
    "text": "The Employee shall indemnify, defend and hold harmless the University and its trustees, officers, agents, and employees from and against any and all suits, judgments, actions, causes of action, claims, demands, liabilities, injuries, expenses, losses, damages and costs (including but not Limited to attorney fees) arising out of, caused by or associated with any sanction imposed by the NCAA and/or the University’s applicable athletics conference at any time against the University and/or the Employee as a result of any violation of NCAA Rules by Employee while employed by the University (in any capacity, pursuant to this Contract or otherwise) or while he was previously employed at another NCAA member institution; or by any coach, staff member, student-athlete, or representative of the institution’s athletics interests, with Employee’s prior knowled ge and consent, or of which Employee should have known.and prevented, or of which Employee learned at any time but failed to report to his institution, while Employee is employed by the University (in any capacity, pursuant to this Contract or otherwise) or while he was previously employed at another NCAA member institution."
  },
  {
    "id": "c097",
    "name": "24.7 Survival",
    "text": "It is hereby agreed that this provision 24.7 shall survive the expiration or earlier termination of this Contract."
  }
]

input.content:
{"judgments": [
  {"clause_id": "c001", "issues": [
    {"issue": "The Application is \"incorporated herein by reference\" but is not attached or described, so what the Employee warranted to be \"complete, accurate and truthful\" cannot be identified from the instrument. The standard of completeness and accuracy is also unmeasured, which matters because 14.1E makes any breach of a warranty just cause.", "type": 1, "prob": 0.24}
  ]},
  {"clause_id": "c002", "issues": [
    {"issue": "The first \"Contract Year\" runs thirteen months (December 16, 2010 to January 15, 2012), which cannot be squared with the per annum amounts payable \"during each Contract Year\" in provisions 3.1, 3.9 and 8.4. Whether the first year earns twelve or thirteen months of those payments is left open.", "type": 2, "prob": 0.16}
  ]},
  {"clause_id": "c003", "issues": [
    {"issue": "The obligation is only to \"meet to discuss\" and the University \"in its sole discretion — may consider\" an extension, so the paragraph creates no measurable duty at all. Whether the meeting requirement is a binding condition or precatory is left to construction.", "type": 1, "prob": 0.13}
  ]},
  {"clause_id": "c004", "issues": [
    {"issue": "The salary is stated to be \"as compensation for his services to the University and satisfactory performance of the terms and conditions of this Contract,\" leaving it ambiguous whether salary is conditioned on the University's judgment of satisfactory performance. \"Satisfactory performance\" is nowhere defined or benchmarked.", "type": 1, "prob": 0.28}
  ]},
  {"clause_id": "c005", "issues": []},
  {"clause_id": "c006", "issues": [
    {"issue": "The promise of \"the standard staff fringe benefits ... as described in the University of Pittsburgh's Staff Handbook\" sits against provision 24.2(d), which reserves to the University the right to modify benefits unilaterally without replacing or compensating the Employee. Which controls a reduction in Handbook benefits is unresolved.", "type": 2, "prob": 0.18}
  ]},
  {"clause_id": "c007", "issues": [
    {"issue": "The club is only \"a mutually agreed upon golf or country club,\" an agreement to agree with no fallback if the parties do not agree. No cap or standard governs the initiation fees and dues the University must pay.", "type": 1, "prob": 0.20}
  ]},
  {"clause_id": "c008", "issues": []},
  {"clause_id": "c009", "issues": [
    {"issue": "The University's obligation ends if the Employee \"fails or refuses to comply fully with the University's requirements for participation in the program,\" but those requirements are neither stated nor incorporated. The trigger is therefore fixed unilaterally by one party.", "type": 1, "prob": 0.12}
  ]},
  {"clause_id": "c010", "issues": [
    {"issue": "\"[T]he same condition existing at the time of receipt ... reasonable wear and tear excepted\" gives no ascertainable standard for when the car has not been maintained. Compliance turns on an undefined comparison of condition over time.", "type": 1, "prob": 0.12}
  ]},
  {"clause_id": "c011", "issues": [
    {"issue": "\"[A]ll Operating expenses ... including without limitation, gasoline and oil\" is a catch-all followed by two consumable specifics, leaving unclear whether repairs, maintenance or insurance fall on the Employee. Provision 3.4 separately says the car is \"fully insured by the University,\" sharpening the scope question.", "type": 1, "prob": 0.16}
  ]},
  {"clause_id": "c012", "issues": [
    {"issue": "The records to be kept are only \"any and all written records concerning the use of the automobile as may be required by the University,\" an obligation whose content the University defines at will. What records exist to be produced is therefore indeterminate.", "type": 1, "prob": 0.10}
  ]},
  {"clause_id": "c013", "issues": [
    {"issue": "The forfeiture turns on whether \"the University reasonably determines\" non-compliance, a self-judging standard with no stated review. The phrase \"any of the above-stated requirements\" also sweeps in 3.4(1)'s program requirements, which are not stated in the Contract.", "type": 1, "prob": 0.13}
  ]},
  {"clause_id": "c014", "issues": [
    {"issue": "The tickets are given \"at no cost\" but \"all of which shall be used for his official responsibilities,\" while provision 10.1D expressly contemplates the Employee reporting income from \"complimentary ticket sales\" as outside athletically related income. The two cannot readily both be given effect.", "type": 2, "prob": 0.14}
  ]},
  {"clause_id": "c015", "issues": [
    {"issue": "Reimbursement is limited to \"appropriate travel and out-of-pocket expenses reasonably incurred,\" with \"appropriate\" and \"reasonably\" left undefined and the University's \"standard procedures\" not incorporated. What qualifies is therefore contestable item by item.", "type": 1, "prob": 0.15}
  ]},
  {"clause_id": "c016", "issues": [
    {"issue": "The bonus schedule is mechanically broken: subparagraph A offers \"the greatest of\" three options of which two are the identical $100,000, the second bonus paragraph carries no letter, and the connectors shift between \"or\" and \"and,\" so whether A, B and C are cumulative or alternative is unclear. The clause also rests on undefined benchmarks such as games \"generally considered a part of the national Bowl Championship Series.\"", "type": 1, "prob": 0.30}
  ]},
  {"clause_id": "c017", "issues": []},
  {"clause_id": "c018", "issues": [
    {"issue": "Provision 3.8 gives the University the \"sole and exclusive right\" to commit the Employee to endorse or consult for shoe, apparel and equipment makers, while provision 10.1D expressly contemplates the Employee having \"endorsement or consultation contracts with athletic shoe, apparel or equipment manufacturers\" whose revenue he retains. The two allocations of the same opportunity conflict.", "type": 2, "prob": 0.22}
  ]},
  {"clause_id": "c019", "issues": [
    {"issue": "The $150,000 is payable \"in two (2) equal installments\" on September 1 and January 1, yet for the thirteen-month first Contract Year the text says only \"(by January 1, 2012 for the first Contract Year),\" leaving unclear whether one or both installments, and how much, are due then. The payment is also conditioned on the Employee \"representing the University as Head Football Coach,\" without saying what happens on mid-year termination.", "type": 1, "prob": 0.22}
  ]},
  {"clause_id": "c020", "issues": [
    {"issue": "The paragraph appears in provision 3.9 but grants the publicity rights \"[i]n relation to the subject of, and the matters described in, this provision 3.8,\" a cross-reference to a different numbered provision. The mislabel makes the scope of the consent uncertain.", "type": 1, "prob": 0.20}
  ]},
  {"clause_id": "c021", "issues": [
    {"issue": "The box is provided \"[s]ubject to the facility owner's standard conditions,\" terms of a third party (Heinz Field) that are neither stated nor limited. The University's obligation is thus defined by a document outside the Contract.", "type": 1, "prob": 0.10}
  ]},
  {"clause_id": "c022", "issues": [
    {"issue": "The requirement to devote \"his full time, attention and energies\" is qualified only by \"any exceptions hereinafter expressly described,\" yet provisions 9.0 (his own football camps) and 10.1 (permission to contract independently with outside sources) allow substantial outside activity. How much outside activity is compatible with the full-time covenant must be worked out between them.", "type": 2, "prob": 0.20}
  ]},
  {"clause_id": "c023", "issues": []},
  {"clause_id": "c024", "issues": [
    {"issue": "The evaluation is to take into account \"prior performance evaluations of the Employee and the expectations and goals previously agreed upon by the Employee and the University's Director of Athletics,\" neither of which existed when this Contract was signed. The criteria for evaluating him are therefore undetermined.", "type": 1, "prob": 0.13}
  ]},
  {"clause_id": "c025", "issues": [
    {"issue": "The enumerated duties close with \"(9) such other duties as assigned from time to time by the University's Director of Athletics,\" an open-ended catch-all sitting against eight specific duties. Because 14.1E makes breach of any duty just cause, the outer boundary of item (9) matters.", "type": 1, "prob": 0.16}
  ]},
  {"clause_id": "c026", "issues": [
    {"issue": "Provision 5.4 subjects NCAA violations to \"disciplinary or corrective action as set forth in the provisions of the NCAA enforcement procedures, including ... termination of employment for significant or repetitive violations,\" while 14.1B makes any violation of NCAA Rules just cause for immediate termination. Whether termination requires a significant or repetitive violation cannot be answered from either alone.", "type": 2, "prob": 0.28}
  ]},
  {"clause_id": "c027", "issues": [
    {"issue": "\"[P]roper regard for the academic welfare of the student-athletes\" and \"fully consistent with the academic standards and policies of the University\" import unstated, unilaterally set standards. Breach of this duty feeds 14.1E, so its vagueness has consequences.", "type": 1, "prob": 0.11}
  ]},
  {"clause_id": "c028", "issues": [
    {"issue": "The declaration that \"[o]verall athletics policy shall remain the exclusive prerogative of the University\" stands against provisions 7.1 and 12.1, which give the Employee input on Team operations and authority to hire, set salaries for and dismiss football staff. Where policy ends and the Employee's reserved authority begins is unresolved.", "type": 2, "prob": 0.11}
  ]},
  {"clause_id": "c029", "issues": [
    {"issue": "The University need only \"permit the Employee to offer input,\" and the list of subjects ends with the catch-all \"other matters pertaining to the operation of the Team,\" so the provision imposes no measurable obligation and no boundary. Final authority is reserved wholly to the Director of Athletics.", "type": 1, "prob": 0.12}
  ]},
  {"clause_id": "c030", "issues": [
    {"issue": "The Employee's availability is owed \"at such times and places as the University may reasonably require,\" with no cap on frequency or duration and \"reasonably\" undefined. The fund-raising duty is expressly open-ended (\"may include, but shall not be limited to\").", "type": 1, "prob": 0.13}
  ]},
  {"clause_id": "c031", "issues": [
